<template><view class="page"><view class="section-title">我的视频</view><view class="muted small">在这台设备上提交的讲解</view><view v-if="error" class="error">{{error}}<button class="button outline" @tap="load">重新加载</button></view><view v-else-if="!items.length" class="empty">还没有视频<view class="link" @tap="capture">去拍一道题</view></view><view v-for="item in items" :key="item.id" class="row" @tap="open(item)"><view class="row-title">{{item.title}}</view><view class="muted small">{{item.mode==='sample'?'固定示例 · ':''}}{{labels[item.status]||item.status}}</view></view></view></template>
<script setup>import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import {request} from '../../lib/api';const items=ref([]),error=ref('');const labels={queued:'排队中',running:'生成中',completed:'已完成',failed:'生成失败',cancelled:'已取消'};async function load(){error.value='';try{items.value=(await request('/api/tasks')).tasks;}catch(e){error.value=e.message;}}onShow(load);const open=t=>uni.navigateTo({url:'/pages/task/index?id='+t.id});const capture=()=>uni.switchTab({url:'/pages/capture/index'});</script>
